def main(data: str) -> dict:
    import datetime
    import json
    import re

    def check_keys(value, path="data"):
        errors = []
        if isinstance(value, dict):
            for key, item in value.items():
                key_text = str(key)
                if not re.search(r"[\u4e00-\u9fff]", key_text) or re.search(r"[A-Za-z]", key_text):
                    errors.append(f"{path}.{key_text}不是纯中文业务键名")
                errors.extend(check_keys(item, f"{path}.{key_text}"))
        elif isinstance(value, list):
            for index, item in enumerate(value):
                errors.extend(check_keys(item, f"{path}[{index}]"))
        return errors

    def time_to_min(value):
        hour, minute = [int(x) for x in str(value).split(":")]
        return hour * 60 + minute

    def min_to_time(value):
        prefix = "次日" if value >= 1440 else ""
        value = value % 1440
        return f"{prefix}{value // 60:02d}:{value % 60:02d}"

    def headway_text(seconds):
        seconds = int(seconds)
        minute = seconds // 60
        remain = seconds % 60
        return f"{minute}分{remain}秒" if remain else f"{minute}分钟"

    if isinstance(data, str):
        if not data.strip():
            raise ValueError("data为空")
        obj = json.loads(data)
    elif isinstance(data, dict):
        obj = data
    else:
        raise TypeError("data必须是JSON字符串或Object")
    if not isinstance(obj, dict):
        raise TypeError("data顶层必须是Object")

    errors = check_keys(obj)
    required_groups = [
        "活动基本信息", "活动日及客流预测", "客流来源及换乘",
        "分时断面预测", "运营基础参数"
    ]
    for name in required_groups:
        if name not in obj:
            errors.append(f"缺少顶层数据组：{name}")
    if errors:
        raise ValueError("；".join(errors))

    base = obj["活动基本信息"]
    days = sorted(obj["活动日及客流预测"], key=lambda x: x["日期"])
    flow = obj["客流来源及换乘"]
    sections = obj["分时断面预测"]
    ops = obj["运营基础参数"]

    for field in ["活动名称", "活动类型", "场馆名称", "邻近车站", "影响线路"]:
        if not base.get(field):
            errors.append(f"活动基本信息.{field}不能为空")
    if not days or not sections or not ops:
        errors.append("活动日、分时断面预测和运营基础参数均不能为空")

    day_keys = [row.get("日期") for row in days]
    if len(day_keys) != len(set(day_keys)) or any(not x for x in day_keys):
        errors.append("活动日日期必须非空且唯一")

    metro_total = 0
    for row in days:
        for field in [
            "日期", "计划开始时间", "计划结束时间", "预计观众人数（人）",
            "预计地铁到场人数（人）", "到场高峰时段", "散场高峰时段",
            "预计疏散时长（分钟）"
        ]:
            if row.get(field) in (None, ""):
                errors.append(f"{row.get('日期', '未知日期')}缺少{field}")
        try:
            datetime.datetime.strptime(row["日期"], "%Y-%m-%d")
            time_to_min(row["计划开始时间"])
            time_to_min(row["计划结束时间"])
        except Exception:
            errors.append(f"{row.get('日期', '未知日期')}日期或时间格式错误")
        for field in ["预计观众人数（人）", "预计地铁到场人数（人）", "预计疏散时长（分钟）"]:
            value = row.get(field)
            if not isinstance(value, (int, float)) or value < 0:
                errors.append(f"{row.get('日期', '未知日期')}{field}必须是非负数")
        if isinstance(row.get("预计地铁到场人数（人）"), (int, float)):
            metro_total += row["预计地铁到场人数（人）"]

    sources = flow.get("主要来源线路", [])
    source_names = [row.get("线路名称") for row in sources]
    if len(source_names) != len(set(source_names)) or any(not x for x in source_names):
        errors.append("主要来源线路名称必须非空且唯一")
    source_total = 0
    share_total = 0
    for row in sources:
        amount = row.get("预测来源客流（人）")
        share = row.get("来源占比（%）")
        if not isinstance(amount, (int, float)) or amount < 0:
            errors.append("预测来源客流必须是非负数")
        else:
            source_total += amount
        if not isinstance(share, (int, float)) or not 0 <= share <= 100:
            errors.append("来源占比必须在0—100之间")
        else:
            share_total += share
    if abs(source_total - metro_total) > 1:
        errors.append("来源客流合计与地铁到场人数合计不一致")
    if abs(share_total - 100) > 0.2:
        errors.append("来源线路占比合计不为100%")
    transfers = flow.get("重点换乘站", [])
    transfer_keys = [(row.get("车站名称"), row.get("换乘方向")) for row in transfers]
    if len(transfer_keys) != len(set(transfer_keys)) or any(not all(x) for x in transfer_keys):
        errors.append("重点换乘站的车站名称和换乘方向必须非空且组合唯一")
    for row in transfers:
        value = row.get("预测换乘客流（人）")
        if not isinstance(value, (int, float)) or value < 0:
            errors.append("预测换乘客流必须是非负数")

    section_keys = []
    worst_by_line = {}
    for row in sections:
        key = (
            row.get("日期"), row.get("时间点或时段"), row.get("线路名称"),
            row.get("方向"), row.get("断面区间")
        )
        section_keys.append(key)
        capacity = row.get("预测运输能力（人/小时）")
        section_flow = row.get("预测断面客流（人/小时）")
        rate = row.get("预测满载率（%）")
        if not all(key):
            errors.append("分时断面预测自然键字段不能为空")
        valid_rate = isinstance(rate, (int, float)) and rate >= 0
        if not isinstance(capacity, (int, float)) or capacity <= 0:
            errors.append("预测运输能力必须大于0")
        elif not isinstance(section_flow, (int, float)) or section_flow < 0:
            errors.append("预测断面客流必须是非负数")
        elif not valid_rate or abs(round(section_flow / capacity * 100, 1) - rate) > 0.2:
            errors.append(f"{row.get('日期')} {row.get('线路名称')}满载率不闭合")
        line = row.get("线路名称")
        current = worst_by_line.get(line)
        if valid_rate and (current is None or rate > current.get("预测满载率（%）", 0)):
            worst_by_line[line] = dict(row)
    if len(section_keys) != len(set(section_keys)):
        errors.append("分时断面预测自然键重复")
    if {row.get("日期") for row in sections} != set(day_keys):
        errors.append("分时断面预测未覆盖全部活动日")

    op_lines = [row.get("线路名称") for row in ops]
    if len(op_lines) != len(set(op_lines)) or any(not x for x in op_lines):
        errors.append("运营基础参数线路名称必须非空且唯一")
    if set(op_lines) != set(base.get("影响线路", [])):
        errors.append("运营基础参数线路与活动影响线路不一致")
    for row in ops:
        if not isinstance(row.get("周末图定行车间隔（秒）"), (int, float)) or row["周末图定行车间隔（秒）"] <= 0:
            errors.append(f"{row.get('线路名称')}图定行车间隔必须大于0")
        last_rows = row.get("邻近车站末班车", [])
        if not last_rows:
            errors.append(f"{row.get('线路名称')}缺少邻近车站末班车")
        last_keys = [(item.get("车站名称"), item.get("方向")) for item in last_rows]
        if len(last_keys) != len(set(last_keys)) or any(not all(x) for x in last_keys):
            errors.append(f"{row.get('线路名称')}末班车车站和方向必须非空且组合唯一")
        for item in last_rows:
            try:
                time_to_min(item.get("图定发车时间", ""))
            except Exception:
                errors.append(f"{row.get('线路名称')}末班车时间格式错误")

    if errors:
        raise ValueError("；".join(errors))

    week_names = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]
    all_last_rows = []
    ops_display = []
    for row in ops:
        item = dict(row)
        item["周末图定行车间隔"] = headway_text(row["周末图定行车间隔（秒）"])
        ops_display.append(item)
        all_last_rows.extend(row["邻近车站末班车"])

    day_result = []
    for row in days:
        date_obj = datetime.datetime.strptime(row["日期"], "%Y-%m-%d")
        start_min = time_to_min(row["计划开始时间"])
        end_min = time_to_min(row["计划结束时间"])
        if end_min < start_min:
            end_min += 1440
        dispersal_end = end_min + int(row["预计疏散时长（分钟）"])
        last_values = []
        for last in all_last_rows:
            last_min = time_to_min(last["图定发车时间"])
            if last_min < start_min:
                last_min += 1440
            last_values.append(last_min)
        earliest_last = min(last_values)
        item = dict(row)
        item["星期"] = week_names[date_obj.weekday()]
        item["预计疏散结束时间"] = min_to_time(dispersal_end)
        item["最早末班车时间"] = min_to_time(earliest_last)
        item["需要计划性延时"] = dispersal_end >= earliest_last
        day_result.append(item)

    worst_rows = sorted(worst_by_line.values(), key=lambda x: x["线路名称"])
    need_extension = any(row["需要计划性延时"] for row in day_result)
    need_extra = any(row["预测满载率（%）"] >= 100 for row in worst_rows)
    decisions = {
        "需要计划性延时": need_extension,
        "运营时间结论": (
            "预计疏散结束不早于最早末班车，需要重新研判延时方案"
            if need_extension else
            "预计疏散结束早于各影响线路最早末班车，不安排计划性延时"
        ),
        "需要计划性加开": need_extra,
        "运力安排结论": (
            "预测断面客流达到或超过运输能力，需要重新研判计划性加开"
            if need_extra else
            "预测断面客流未超过运输能力，不安排计划性加开"
        ),
        "备用车原则": "不额外增加备用车，保留既有备用车、回厂车和退峰列车动态投入条件"
    }

    first_date = datetime.datetime.strptime(days[0]["日期"], "%Y-%m-%d")
    last_date = datetime.datetime.strptime(days[-1]["日期"], "%Y-%m-%d")
    if first_date.date() == last_date.date():
        date_title = f"{first_date.year}年{first_date.month}月{first_date.day}日"
        short_range = f"{first_date.month}月{first_date.day}日"
    elif first_date.year == last_date.year and first_date.month == last_date.month:
        date_title = f"{first_date.year}年{first_date.month}月{first_date.day}日—{last_date.day}日"
        short_range = f"{first_date.month}月{first_date.day}日—{last_date.day}日"
    else:
        date_title = (
            f"{first_date.year}年{first_date.month}月{first_date.day}日—"
            f"{last_date.year}年{last_date.month}月{last_date.day}日"
        )
        short_range = f"{first_date.month}月{first_date.day}日—{last_date.month}月{last_date.day}日"

    report_title = f"{date_title}{base['活动名称']}运营组织安排"
    event_display = base["活动名称"]
    if event_display.startswith(base["场馆名称"]):
        event_display = event_display[len(base["场馆名称"]):].strip() or base["活动名称"]
    weekdays = "、".join(row["星期"] for row in day_result)
    day_sentences = []
    for row in day_result:
        date_obj = datetime.datetime.strptime(row["日期"], "%Y-%m-%d")
        day_sentences.append(
            f"{date_obj.month}月{date_obj.day}日计划{row['计划结束时间']}结束，"
            f"预计观众约{row['预计观众人数（人）'] / 10000:.1f}万人"
        )
    line_text = "、".join(str(x).replace("号线", "") for x in base["影响线路"]) + "号线"
    if "连通" in base.get("场馆与车站关系", ""):
        station_text = f"活动场馆与地铁{line_text}{base['邻近车站']}连通"
    else:
        station_text = f"活动场馆邻近地铁{line_text}{base['邻近车站']}"
    intro = (
        f"{short_range}（{weekdays}），{base['场馆名称']}将举办{event_display}。"
        f"活动每日{day_result[0]['计划开始时间']}开始，" + "；".join(day_sentences) + "。"
        f"{station_text}，预计活动期间地铁到场客流合计约{metro_total / 10000:.2f}万人。"
        f"根据《地铁沿线活动运输调整指导意见》，结合活动规模、结束时间、客流预测及周末运营基础，"
        f"运营组织安排具体如下："
    )

    first_part = {
        "活动基本信息": base,
        "活动日评价": day_result,
        "客流来源及换乘": flow,
        "最不利断面": worst_rows,
        "运营基础参数": ops_display,
        "确定性结论": decisions
    }
    second_part = {
        "活动基本信息": base,
        "活动日评价": day_result,
        "客流来源及换乘": flow,
        "确定性结论": decisions
    }
    third_part = {
        "活动基本信息": base,
        "活动日评价": day_result,
        "客流来源及换乘": flow,
        "最不利断面": worst_rows,
        "确定性结论": decisions
    }

    return {
        "report_title": report_title,
        "intro_md": intro,
        "part1_data": first_part,
        "part2_data": second_part,
        "part3_data": third_part
    }

def main(
    report_title: str,
    intro_md: str,
    part1_md: str,
    part2_md: str,
    part3_md: str
) -> dict:
    import re

    def clean(value, name):
        text = str(value or "").strip()
        if not text:
            raise ValueError(f"{name}为空")
        if text.startswith("```") or text.startswith("{") or text.startswith("["):
            raise ValueError(f"{name}必须直接输出Markdown，不能输出代码围栏或JSON")
        return text

    part1 = clean(part1_md, "第一部分")
    part2 = clean(part2_md, "第二部分")
    part3 = clean(part3_md, "第三部分")
    intro = clean(intro_md, "导语")

    groups = [
        (part1, ["## 一、活动信息", "## 二、运营时间及运力安排"]),
        (part2, ["## 三、客运及安全保障", "## 四、行车组织", "## 五、信息发布"]),
        (part3, ["## 六、客流分析统计", "## 七、信息报送", "## 八、设备保障", "## 九、其他事项"])
    ]
    for text, headings in groups:
        positions = []
        for heading in headings:
            matches = list(re.finditer(rf"(?m)^{re.escape(heading)}\s*$", text))
            if len(matches) != 1:
                raise ValueError(f"标题必须且只能出现一次：{heading}")
            positions.append(matches[0].start())
        if positions != sorted(positions):
            raise ValueError("模型输出章节顺序错误")
        if text[:positions[0]].strip():
            raise ValueError("模型输出首个章节标题前存在多余文字")

    report = (
        f"# {report_title}\n\n{intro}\n\n"
        f"{part1}\n\n{part2}\n\n{part3}\n"
    )
    all_headings = [
        "## 一、活动信息", "## 二、运营时间及运力安排",
        "## 三、客运及安全保障", "## 四、行车组织", "## 五、信息发布",
        "## 六、客流分析统计", "## 七、信息报送",
        "## 八、设备保障", "## 九、其他事项"
    ]
    positions = []
    for heading in all_headings:
        matches = list(re.finditer(rf"(?m)^{re.escape(heading)}\s*$", report))
        if len(matches) != 1:
            raise ValueError(f"最终报告标题必须且只能出现一次：{heading}")
        positions.append(matches[0].start())
    if positions != sorted(positions):
        raise ValueError("最终报告九章顺序错误")

    return {
        "report_md": report,
        "report_len": len(report)
    }
